/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  var st = [0, 20, 38, 57], en = [20, 38, 57, 94];
  phases([[0,20],[20,38],[38,57],[57,78]]);
  var cur = 3; for (var i = 0; i < 4; i++) if (p >= st[i] && p < en[i]) cur = i;
  for (var i = 0; i < 4; i++) {
    var s = st[i], e = en[i];
    v['vw'+i] = (p >= s && p < e) ? Math.min(lin([[s,0],[s+1.2,1]]), i < 3 ? 1 - lin([[e-1,0],[e,1]]) : out) : 0;
    v['tb'+i] = cur === i ? 1 : 0;
    v['r'+i] = p >= s + 1 ? out : 0.35 * out;
    v['k'+i] = (p >= e - 3 && p < 97) ? out : 0;
  }
  v.k3 = (p >= 76 && p < 97) ? out : 0;
  v.fin = (p >= 78 && p < 97) ? out : 0;

  v.a0 = lin([[6,0],[12,1]]); v.a1 = lin([[25,0],[31,1]]); v.a2 = lin([[44,0],[50,1]]); v.a3 = lin([[62,0],[68,1]]);

  return { v: v };}

